			function setInsptnTrprYn(poData1, poData2){
			    var objDs = app.lookup("dsCaseChupList");
			    if(objDs.getRowCount() == 0) {
			        objDs.addRow();
			    }

			    sAge = cpr.utils.Util.toNumber(poData1) - 1; //만나이

			    var bChecked = false;
			    var sCheckYn = "N";
			    var sMsgCn   = "";
			    
			    if(poData2 != "READ"){
			        util.Control.setVisible(app, true, ["btn5", "opt16"]); // 첨부파일 저장
			    } else {
			        util.Control.setVisible(app, false, ["btn5", "opt16"]); // 첨부파일 저장
			    }    
			    
			    if(poData2 == "CREATE"){
			        var dsHpeSrvc = app.lookup("dsHpeSrvc")
			        if(dsHpeSrvc.getRowCount() == 0){
			            dsHpeSrvc.addRow();    
			        }
			        dsHpeSrvc.setValue(0, "EXMN_YMD", vsToday);    
			    }
			    
			    if(sAge < 19) {
			        
			        if(poData2 == "CREATE") {
			            bChecked = true;
			            sCheckYn = "Y";
			            sMsgCn   = "19세 미만 수검대상자 입니다.";
			        } else {
			            var dsChupList    = app.lookup("dsChupList");
			            var sMaxInsptnYmd = dsChupList.getMax("INSPTN_YMD");
			            
			            //if(!cpr.utils.Util.isNullOrEmpty(sMaxInsptnYmd)) {
			            if(!ValueUtil.isNull(sMaxInsptnYmd)){
			                var nElpsYycnt = Math.floor(DateUtil.getDiffDay(sMaxInsptnYmd, vsToday) / 365)
			                if(nElpsYycnt > 3) {
			                    bChecked = true;
			                    sCheckYn = "Y";
			                    sMsgCn   = "19세 미만이고 수검일로부터 3년이 경과되어 수검대상자 입니다.";
			                } else {
			                    sMsgCn   = "19세 미만이지만 3년 이내 수검이력이 있어 수검대상자가 아닙니다.";
			                }
			            } else {
			                bChecked = true;
			                sCheckYn = "Y";

			                if(dsChupList.getRowCount() > 0) {                    
			                    sMsgCn   = "19세 미만이고 수검이력이 존재하지만 수검일자가 존재하지 않습니다.";
			                } else {
			                    sMsgCn   = "19세 미만이고 수검이력이 존재하지 않아 수검대상자 입니다.";
			                }
			            }
			        }
			    } else {
			        sMsgCn = "19세 이상 수검대상자가 아닙니다.";
			    }

			    sInsptnTrprYn = sCheckYn;

			    app.lookup("cominfomsg1").InfoMessage = sMsgCn;
			    app.lookup("cbx4").checked = bChecked;
			    objDs.setValue(0, "CHUP_INSPTN_TRPR_YN", sCheckYn);
			    
			    var dsCrisisScrenn = app.lookup("dsCrisisScrenn");
			    if(dsCrisisScrenn.getRowCount() == 0){
			        dsCrisisScrenn.addRow();
			        dsCrisisScrenn.setValue(0, "CASE_MNG_NO", sCaseMngNo);
			        dsCrisisScrenn.setValue(0, "CASE_MNG_ODRNO", sCaseMngOdrno);
			        dsCrisisScrenn.setValue(0, "CRISIS_SCRENN_YN", "N");
			        dsCrisisScrenn.setValue(0, "CLIENA_RPT_YN", "N");
			        dsCrisisScrenn.setValue(0, "OUTHFA_FTSPT_EXPMN_YN", "N");
			        dsCrisisScrenn.setValue(0, "ETC_CRISIS_SITTN_SGN_YN", "N");
			    }
			    if(ValueUtil.isNull(dsCrisisScrenn.getValue(0, "INSP_YMD"))){
			        dsCrisisScrenn.setValue(0, "INSP_YMD", vsToday);
			    }
			    
			    if(ValueUtil.isNull(dsCrisisScrenn.getValue(0, "CHIL_ILTRT_QUSTNB_TYPE_SE_CD"))){
			        if(sAge >= 9 && sAge <= 10){
			            dsCrisisScrenn.setValue(0, "CHIL_ILTRT_QUSTNB_TYPE_SE_CD", "01");
			        //} else if(sAge >= 11 && sAge <= 24){
			        } else if(sAge >= 11){
			            dsCrisisScrenn.setValue(0, "CHIL_ILTRT_QUSTNB_TYPE_SE_CD", "02");
			        } 
			        /*
			        else {
			            // 9 ~ 24세가 아닌 경우 위기스크리닝 숨긴다.
			            util.Control.setVisible(app, false, ["grp7"]);
			        }
			        */
			    }
			    util.Control.redraw(app, "grpData");   
			    dsCrisisScrenn.commit();
			}
